def kthBalancedSequence(n, k):
    m = 2 * n
    ways = [[0] * (m + 3) for _ in range(m + 1)]
    ways[0][0] = 1
    for r in range(1, m + 1):
        for b in range(0, m + 1):
            ways[r][b] = ways[r - 1][b + 1] + (ways[r - 1][b - 1] if b > 0 else 0)
    out = []
    bal = 0
    for pos in range(m):
        rem = m - pos - 1
        open_count = ways[rem][bal + 1]
        if k <= open_count:
            out.append("(")
            bal += 1
        else:
            k -= open_count
            out.append(")")
            bal -= 1
    return "".join(out)
